    {
     "heading": "「與人交流」：六大必備技能中愈來愈稀缺的一項",
     "heading_en": "Interpersonal Communication: An Increasingly Scarce Core Skill",
     "body": [
      "在 iKala，ChatGPT、Duet AI 等工具一出現，作者都要同仁去試玩、試用，不能跟不上科技與世界潮流。他也看到年輕同仁對數位工具有強大認知、在虛擬世界存在感很強，但人與人之間的交流互動能力明顯弱化。因此他特別把「**與人交流**」列為員工必備**六大技能**之一：當大家把時間花在機器上、只想與機器溝通時，當面交流的能力就格外珍貴且稀缺。",
      "疫情後辦公室的意義也變了。百年來人類對辦公室最大的假設是「完成工作」的地點；但 iKala 調查顯示，**38.1%**同仁認為在家與在公司效率沒差，**42.5%**認為在家效率較好——超過8成在家工作反而有助生產力。要注意的是，同仁太久沒見面，**向心力降低了**。"
     ]
    },
    {
     "heading": "重新定義辦公室：交流、協作與專注的兩極化設計",
     "heading_en": "Redefining the Office: A Polarized Design for Connection, Collaboration, and Focus",
     "body": [
      "因此 iKala 依重要性，把辦公室的功能設定為：人與人面對面交流的場域、團隊協作的地點，以及安靜獨立工作的空間。硬體上採取**兩極化策略**——既有開放式空間，也有方便個人完成工作的私密「電話亭」，兩種都是剛需，而且必須混搭。",
      "一走進 iKala，左邊是開放寬敞的空間，有沙發、圓桌和高腳椅，工作累了可以拿點零食、在沙發小憩、和同事聊天，快速充飽電力。獨立私密的電話亭有空調又安靜，給需要專注的同仁使用，有些人甚至燈一關就睡起來——作者認為適時休息也很好，還說 iKala 若搬家，電話亭應該會再增加一倍。"
     ]
    },
    {
     "heading": "回到辦公室與刻意製造交流：維持「心智正常」",
     "heading_en": "Back to the Office and Engineered Interaction: Keeping Minds Healthy",
     "body": [
      "雖然實施彈性上班，作者仍要主管盡量叫同仁進辦公室——不是為了盯人，而是疫情關了大家幾年，當面交流愈來愈少，可能扭曲心智。進不進辦公室由主管決定；有主管一週只來兩天，就要求團隊同一天進來。所有人都能獨立完成工作，但共同討論、協作、打屁同樣重要。",
      "iKala 也刻意增加交流機會：人資邀外部老師開美術、繪畫等課程，有同仁一直畫圓圈圈，沒什麼意義卻能一起紓壓，報名總是秒殺；邀廠商試吃、鼓勵同仁跟既有客戶團購；每年舉辦員工旅遊，因超過200人不便出動，另補助各部門做 [[team building|Team Building]]，從生存遊戲、唱歌到吃吃喝喝，目的都是維持大家的「心智正常」。"
     ]
    }
